DO $$ DECLARE s text; BEGIN SELECT pg_get_functiondef(oid) INTO s FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='record_termination_notice'; s:=replace(s,'INSERT INTO launch_events(launch_id,user_id,kind,note) VALUES(l.id,auth.uid(),''termination_notice'',n||'' signed-plan exit items generated'')','INSERT INTO launch_events(launch_id,user_id,kind,details) VALUES(l.id,auth.uid(),''termination_notice'',jsonb_build_object(''items_generated'',n))'); EXECUTE s; SELECT pg_get_functiondef(oid) INTO s FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='_finish_plan_exit'; s:=replace(s,'INSERT INTO launch_events(launch_id,user_id,kind,note) VALUES(l.id,auth.uid(),''closed'',CASE WHEN _override IS NULL THEN ''All exit items Done'' ELSE ''Admin override: ''||trim(_override) END)','INSERT INTO launch_events(launch_id,user_id,kind,details) VALUES(l.id,auth.uid(),''closed'',jsonb_build_object(''note'',CASE WHEN _override IS NULL THEN ''All exit items Done'' ELSE ''Admin override: ''||trim(_override) END))'); EXECUTE s; END $$;
CREATE FUNCTION public.exit_task_metadata_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (NEW.exit_stage IS DISTINCT FROM OLD.exit_stage OR NEW.exit_owner_side IS DISTINCT FROM OLD.exit_owner_side OR NEW.exit_financial IS DISTINCT FROM OLD.exit_financial) THEN RAISE EXCEPTION 'Generated exit scope is immutable; edit the template for future exits'; END IF; RETURN NEW; END $$;
CREATE TRIGGER exit_task_metadata_guard BEFORE UPDATE ON public.client_tasks FOR EACH ROW EXECUTE FUNCTION public.exit_task_metadata_guard();
CREATE FUNCTION public.exit_template_validate() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF length(trim(NEW.item_text))<1 OR length(NEW.item_text)>2000 OR length(trim(NEW.stage))<1 OR length(NEW.stage)>120 OR (NEW.working_days AND NEW.offset_days<0) THEN RAISE EXCEPTION 'Provide a valid exit item, stage and working-day offset'; END IF; IF NEW.custom_plan_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM custom_plans c JOIN plan_versions v ON v.id=c.base_plan_version_id WHERE c.id=NEW.custom_plan_id AND v.plan_id=NEW.plan_id) THEN RAISE EXCEPTION 'Custom checklist must use its base plan'; END IF; RETURN NEW; END $$;
CREATE TRIGGER exit_template_validate BEFORE INSERT OR UPDATE ON public.exit_checklist_items FOR EACH ROW EXECUTE FUNCTION public.exit_template_validate();